324	/// Persistent state for an in-progress `push` run.
325	///
326	/// Serialized as flat TOML (`key = "value"`) under the dir/file
327	/// configured in `.vc-config.toml`'s `[push]` section. Fields added
328	/// across dev steps are all `Option<_>` so older states remain
329	/// loadable — only `version` / `stage` / `bookmark` / `started_at`
330	/// are required. See the module docstring for which dev step
331	/// introduced which field.
332	#[derive(Debug, Clone, PartialEq, Eq)]
333	pub struct PushState {
334	    /// State-file format version; must match `STATE_FORMAT_VERSION`
335	    /// to be considered readable.
336	    pub version: u32,
337	    /// The next stage to execute on resume.
338	    pub stage: Stage,
339	    /// Work-repo bookmark being advanced by this run (persisted so
340	    /// resume doesn't need `--bookmark` again). The bot repo's
341	    /// side is pinned to `BOT_BOOKMARK`, not stored here.
342	    pub bookmark: String,
343	    /// ISO-8601 UTC timestamp captured when the state was first
344	    /// written. Informational — helps the user spot stale state.
345	    pub started_at: String,
346	    /// Work-repo changeID captured at `message` stage (before
347	    /// `commit-work` runs). Stable across `jj commit` — becomes the
348	    /// chid of the just-committed change. Used when composing the
349	    /// `.claude` commit's ochid trailer. Added in 0.37.0-2.
350	    pub work_chid: Option<String>,
351	    /// `.claude` repo changeID used by the work-repo commit's ochid
352	    /// trailer. Either the pre-commit `@` chid (when `.claude` has
353	    /// pending changes — becomes `@-` after commit) or the current
354	    /// `@-` chid (when `.claude` is clean — stays stable). Added in
355	    /// 0.37.0-2.
356	    pub bot_chid: Option<String>,
357	    /// Whether `.claude`'s working copy had changes at `message`
358	    /// time. Decides whether `commit-bot` actually runs or
359	    /// skips. Added in 0.37.0-2.
360	    pub bot_had_changes: Option<bool>,
361	    /// `jj op` id of the work repo captured before `commit-work`. On
362	    /// failure in stages 4-6, `jj op restore` rewinds here. Added
363	    /// in 0.37.0-2.
364	    pub op_work: Option<String>,
365	    /// `jj op` id of `.claude` captured before `commit-work`. Same
366	    /// rollback target as `op_work`. Added in 0.37.0-2.
367	    pub op_bot: Option<String>,
368	    /// Composed commit title — persisted so resume doesn't need
369	    /// `--title` re-passed. Set during `message` stage from either
370	    /// `--title` or `$EDITOR`. Added in 0.37.0-4.
371	    pub title: Option<String>,
372	    /// Composed commit body (sans ochid trailer, which each commit
373	    /// stage appends). Persisted alongside title. Multi-line
374	    /// content is escaped for the flat-TOML save format (see
375	    /// `escape_multiline` / `unescape_multiline`). Added in
376	    /// 0.37.0-4.
377	    pub body: Option<String>,
378	}
379	
380	impl PushState {
381	    /// Build a fresh state for a new run.
382	    pub fn new_for(bookmark: &str) -> Self {
383	        PushState {
384	            version: STATE_FORMAT_VERSION,
385	            stage: Stage::first(),
386	            bookmark: bookmark.to_string(),
387	            started_at: Utc::now().to_rfc3339(),
388	            work_chid: None,
389	            bot_chid: None,
390	            bot_had_changes: None,
391	            op_work: None,
392	            op_bot: None,
393	            title: None,
394	            body: None,
395	        }
396	    }
397	
398	    /// Write the state to `path`, creating parent dirs as needed.
399	    ///
400	    /// Values are single-line and contain no `"` characters under
401	    /// normal operation (stage names are kebab-case, chids are
402	    /// ASCII, bookmark names don't contain quotes, timestamps are
403	    /// ASCII). A defensive escape pass replaces any stray `"` with
404	    /// `\"` so the file always parses with `toml_simple`. Optional
405	    /// fields are only emitted when set so older state files don't
406	    /// carry a wall of blank keys.
407	    pub fn save(&self, path: &Path) -> Result<(), Box<dyn std::error::Error>> {
408	        if let Some(parent) = path.parent() {
409	            fs::create_dir_all(parent)?;
410	        }
411	        let mut content = String::new();
412	        content.push_str("# vc-x1 push state — managed file, do not edit by hand\n");
413	        content.push_str("[push-state]\n");
414	        content.push_str(&format!("version = {}\n", self.version));
415	        content.push_str(&format!("stage = \"{}\"\n", self.stage.as_str()));
416	        content.push_str(&format!("bookmark = \"{}\"\n", escape_toml(&self.bookmark)));
417	        content.push_str(&format!(
418	            "started_at = \"{}\"\n",
419	            escape_toml(&self.started_at)
420	        ));
421	        if let Some(v) = &self.work_chid {
422	            content.push_str(&format!("work_chid = \"{}\"\n", escape_toml(v)));
423	        }
424	        if let Some(v) = &self.bot_chid {
425	            content.push_str(&format!("bot_chid = \"{}\"\n", escape_toml(v)));
426	        }
427	        if let Some(v) = self.bot_had_changes {
428	            content.push_str(&format!("bot_had_changes = {v}\n"));
429	        }
430	        if let Some(v) = &self.op_work {
431	            content.push_str(&format!("op_work = \"{}\"\n", escape_toml(v)));
432	        }
433	        if let Some(v) = &self.op_bot {
434	            content.push_str(&format!("op_bot = \"{}\"\n", escape_toml(v)));
435	        }
436	        if let Some(v) = &self.title {
437	            content.push_str(&format!("title = \"{}\"\n", escape_multiline(v)));
438	        }
439	        if let Some(v) = &self.body {
440	            content.push_str(&format!("body = \"{}\"\n", escape_multiline(v)));
441	        }
442	        fs::write(path, content)?;
443	        debug!("push: wrote state to {}", path.display());
444	        Ok(())
445	    }
446	
447	    /// Load state from `path`, returning `Ok(None)` if the file is
448	    /// absent (a fresh run) and `Err` if the file exists but is
449	    /// unusable (stale format, missing required keys, unknown stage).
450	    pub fn load(path: &Path) -> Result<Option<Self>, Box<dyn std::error::Error>> {
451	        if !path.exists() {
452	            return Ok(None);
453	        }
454	        let map = toml_load(path)?;
455	        let require = |k: &str| -> Result<String, Box<dyn std::error::Error>> {
456	            map.get(k)
457	                .cloned()
458	                .ok_or_else(|| format!("push state {}: missing key '{k}'", path.display()).into())
459	        };
460	        let version: u32 = require("push-state.version")?
461	            .parse()
462	            .map_err(|e| format!("push state {}: invalid version: {e}", path.display()))?;
463	        if version != STATE_FORMAT_VERSION {
464	            return Err(format!(
465	                "push state {}: unsupported format version {version} (expected {}); \
466	                 re-run with --restart to start fresh",
467	                path.display(),
468	                STATE_FORMAT_VERSION
469	            )
470	            .into());
471	        }
472	        let stage_str = require("push-state.stage")?;
473	        let stage = Stage::from_str(&stage_str)
474	            .ok_or_else(|| format!("push state {}: unknown stage '{stage_str}'", path.display()))?;
475	        let bot_had_changes = match map.get("push-state.bot_had_changes") {
476	            Some(s) => Some(s.parse::<bool>().map_err(|e| {
477	                format!(
478	                    "push state {}: invalid bot_had_changes: {e}",
479	                    path.display()
480	                )
481	            })?),
482	            None => None,
483	        };
484	        Ok(Some(PushState {
485	            version,
486	            stage,
487	            bookmark: require("push-state.bookmark")?,
488	            started_at: require("push-state.started_at")?,
489	            work_chid: map.get("push-state.work_chid").cloned(),
490	            bot_chid: map.get("push-state.bot_chid").cloned(),
491	            bot_had_changes,
