}

impl PushState {
    /// Build a fresh state for a new run.
    pub fn new_for(bookmark: &str) -> Self {
        PushState {
            version: STATE_FORMAT_VERSION,
            stage: Stage::first(),
            bookmark: bookmark.to_string(),
            started_at: Utc::now().to_rfc3339(),
            work_chid: None,
            bot_chid: None,
