    layout: &StateLayout,
) -> Result<(String, String), Box<dyn std::error::Error>> {
    let editor = std::env::var("EDITOR")
        .or_else(|_| std::env::var("VISUAL"))
        .unwrap_or_else(|_| "vi".to_string()); // OK: POSIX fallback when nothing is configured

