/// Whether `bookmark`'s local position matches its remote-tracking
/// position.
///
/// `<bookmark>@origin` is an ordinary revision to jj, so this is a
/// chid comparison rather than a parse of `bookmark list` output.
/// A bookmark that has never been pushed has no such revision and
/// counts as unpublished, routing the run through `push-work` — the
/// safe direction, since pushing an already-published bookmark is a
/// no-op while skipping an unpublished one loses the publish.
fn is_bookmark_published(root: &Path, bookmark: &str) -> Result<bool, Box<dyn std::error::Error>> {
    let remote_rev = format!("{bookmark}@origin");
    if !jj::rev_exists(root, &remote_rev)? {
        return Ok(false);
    }
    Ok(jj::chid_of(root, &remote_rev)? == jj::chid_of(root, bookmark)?)
}

