//! Where a push run should start, derived from the repos rather
//! than read from a state file.
//!
//! The state file records where the *last process* stopped, which
//! is only the same thing as where the *next process* should start
//! while nothing else moves. A rollback moves things: it rewinds
//! the repos to pre-commit and leaves the recorded stage untouched,
//! so the rerun resumes past work it just undid (bugs.md #3). The
//! repos cannot go stale about themselves, so they are the better
//! source.
//!
//! Four observable states, checked in order:
//!
//! - Work `@` has pending changes — nothing has been committed for
//!   this run; start from the top.
//! - Committed, bookmark not yet on the new tip — resume at
//!   `bookmark-set`.
//! - Bookmark on the tip but not published — resume at `push-work`.
//!   This is the one genuine cross-process resume: `push-work`
//!   failed with the commits already made.
//! - Bookmark published — only the bot side can be outstanding;
//!   resume at `squash-push-bot`.
//!
//! The derivation is deliberately blind to *why* a repo looks the
//! way it does. A publish-only run (commits already made by hand or
//! by an earlier push, only the bookmark and remote left to move —
//! the trapezoid recipe's final step) is indistinguishable from a
//! resume after a failure, and should be: both want the same work
//! done.

use std::path::Path;

use log::debug;

use crate::jj;

use super::state::Stage;

/// The stage a run should start at, derived from repo state.
///
/// `bookmark` is the work-repo bookmark the run advances. Returns
/// `Stage::first()` whenever the work repo still holds uncommitted
/// changes, which is the ordinary fresh-run case.
pub(super) fn derive_resume_stage(
    root: &Path,
    bookmark: &str,
) -> Result<Stage, Box<dyn std::error::Error>> {
    if !jj::is_empty(root, "@")? {
        debug!("push resume: work `@` has pending changes → fresh run");
        return Ok(Stage::first());
    }

    // An empty `@` means the commits (if any) are already sealed;
    // `@-` is the tip this run would publish.
    if !jj::rev_exists(root, bookmark)? {
        debug!("push resume: bookmark '{bookmark}' does not exist yet → bookmark-set");
        return Ok(Stage::BookmarkSet);
    }

    let tip_chid = jj::chid_of(root, "@-")?;
    let bookmark_chid = jj::chid_of(root, bookmark)?;
    if bookmark_chid != tip_chid {
        debug!(
            "push resume: bookmark '{bookmark}' at {bookmark_chid}, tip is {tip_chid} \
             → bookmark-set"
        );
        return Ok(Stage::BookmarkSet);
    }

    if is_bookmark_published(root, bookmark)? {
        debug!("push resume: '{bookmark}' matches its remote → squash-push-bot");
        Ok(Stage::SquashPushBot)
    } else {
        debug!("push resume: '{bookmark}' is ahead of its remote → push-work");
        Ok(Stage::PushWork)
    }
}

/// Whether `bookmark`'s local position matches its remote-tracking
/// position.
///
/// Reads the `@origin` line out of `jj bookmark list --all-remotes`.
/// An untracked or never-pushed bookmark has no such line and counts
/// as unpublished, which routes the run through `push-work` — the
/// safe direction, since `push-work` on an already-published
/// bookmark is a no-op.
fn is_bookmark_published(
    root: &Path,
    bookmark: &str,
) -> Result<bool, Box<dyn std::error::Error>> {
    let listing = jj::bookmark_list_all(root, bookmark)?;
    // jj marks a bookmark whose local position differs from the
    // remote with a `*` suffix on the bookmark name; a matching
    // remote line is printed without one.
    let published = listing
        .lines()
        .any(|line| line.trim_start().starts_with("@origin"))
        && !listing
            .lines()
            .any(|line| line.starts_with(&format!("{bookmark}*")));
    Ok(published)
}

