/// Print where a run would start and return.
///
/// Reports the derived stage — what the repos say the next run does
/// — and, while the state file still exists, what it recorded. The
/// two differing is the interesting case: it means a rollback (or an
/// out-of-band fix) moved the repos without moving the record, which
/// is what `--status` is for noticing.
fn cmd_status(
    root: &Path,
    params: &PushParams,
    layout: &StateLayout,
) -> Result<(), Box<dyn std::error::Error>> {
    let saved = PushState::load(&layout.path)?;
    let bookmark = params
        .bookmark
        .clone()
        .or_else(|| saved.as_ref().map(|s| s.bookmark.clone()));
    match &bookmark {
        Some(b) => info!(
            "push-status: derived stage={} (bookmark {b})",
            resume::derive_resume_stage(root, b)?.as_str()
        ),
        None => info!(
            "push-status: no bookmark to derive from — pass one \
             (`vc-x1 push <bookmark> --status`)"
        ),
    }
    match saved {
        Some(state) => info!(
            "push-state: stage={} bookmark={} started={} (file: {})",
            state.stage.as_str(),
            state.bookmark,
            state.started_at,
            layout.path.display()
        ),
        None => info!(
            "push-state: no saved state ({} does not exist)",
            layout.path.display()
        ),
    }
    Ok(())
}

